// AUTOGENERATED. DO NOT MODIFY.
// To modify this file, run: node scripts/m3/gen-keyboard-tests.mjs menu
// Spec: m3.material.io 2026-10-13_06-10-19, menus "Keyboard navigation"
//
// Each case presses real keys and checks the behavior the spec's keyboard
// table lists for that key. `xit` cases are known differences from the spec.

// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-menu.js';
import './md-gb-menu-item.js';
import {type MenuElement} from './menu-element.js';

interface Fixture {
  root: HTMLElement;
  items: HTMLElement[];
  before: HTMLElement;
  after: HTMLElement;
  /** Indices of the items that received a click (activation). */
  activated: number[];
  // Menus.
  invoker?: HTMLElement;
  menu?: HTMLElement;
  submenu?: HTMLElement;
  submenuItems?: HTMLElement[];
}

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

function fixture(root: HTMLElement, items: HTMLElement[]): Fixture {
  const activated: number[] = [];
  items.forEach((item, i) => {
    item.addEventListener('click', (event) => {
      // Clicks bubbling from nested items (submenus) are not this item's.
      const path = event.composedPath();
      if (path.find((el) => items.includes(el as HTMLElement)) === item) {
        activated.push(i);
      }
    });
  });
  return {
    root,
    items,
    activated,
    before: root.querySelector<HTMLElement>('#before')!,
    after: root.querySelector<HTMLElement>('#after')!,
  };
}

/** Waits for Lit updates, a frame and pending timeouts. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  // Twice: popover toggle events, and the timeouts they start, can land
  // after the next frame.
  for (let i = 0; i < 2; i++) {
    await new Promise((resolve) => requestAnimationFrame(resolve));
    await new Promise((resolve) => setTimeout(resolve));
  }
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** The focused element and the focused elements of its shadow roots. */
function focusPath() {
  const path: Element[] = [];
  let el = document.activeElement;
  while (el) {
    path.push(el);
    el = el.shadowRoot?.activeElement ?? null;
  }
  return path;
}

function isFocused(target: Element) {
  return focusPath().includes(target);
}

/** The index of the item that holds focus, or -1. */
function focusedIndex(items: Element[]) {
  const path = focusPath();
  return items.findIndex((item) =>
    path.some((el) => el === item || item.contains(el)),
  );
}

/** Focuses item `index` (negative counts from the end). */
async function focusItem(f: Fixture, index: number) {
  f.items[(index + f.items.length) % f.items.length].focus();
  await settle();
}

async function setup(): Promise<Fixture> {
  const root = await mount(html`
    <button id="before">Before</button>
    <button id="invoker" popovertarget="menu">Edit</button>
    <md-gb-menu id="menu">
      <md-gb-menu-item>Cut</md-gb-menu-item>
      <md-gb-menu-item>Copy</md-gb-menu-item>
      <md-gb-menu-item>Paste</md-gb-menu-item>
      <md-gb-menu-item>
        Share
        <md-gb-menu slot="submenu" id="submenu">
          <md-gb-menu-item>Email</md-gb-menu-item>
          <md-gb-menu-item>Message</md-gb-menu-item>
        </md-gb-menu>
      </md-gb-menu-item>
    </md-gb-menu>
    <button id="after">After</button>
  `);
  const menu = root.querySelector<MenuElement>('#menu')!;
  const submenu = root.querySelector<MenuElement>('#submenu')!;
  return {
    ...fixture(root, menu.items),
    menu,
    submenu,
    submenuItems: submenu.items,
    invoker: root.querySelector<HTMLElement>('#invoker')!,
  };
}

function isOpen(menu: Element) {
  return menu.matches(':popover-open');
}

/**
 * Opens the menu from its invoker, as a click would, and waits for the
 * menu's (async) toggle event, which focuses its first item.
 */
async function openMenu(f: Fixture) {
  const opened = new Promise((resolve) => {
    f.menu.addEventListener('toggle', resolve, {once: true});
  });
  f.invoker.focus();
  f.invoker.click();
  await opened;
  await settle();
}

describe('<md-gb-menu> keyboard (spec)', () => {
  afterEach(() => {
    container?.remove();
    container = undefined;
  });

  // Spec: "Tab" | "Focus lands on menu"
  // spec: menus-0b5f38
  describe("Tab: Focus lands on menu", () => {
    it("Tab moves focus to the menu button", async () => {
      const f = await setup();
      f.before.focus();
      await press('Tab');
      expect(isFocused(f.invoker)).toBeTrue();
    });
  });

  // Spec: "Space or Enter" | "For closed menus: Opens menu or submenu For open menus: Selects a menu item"
  // spec: menus-9d8c12, menus-b690c3, menus-87fdb8
  describe("Space or Enter: For closed menus: Opens menu or submenu For open menus: Selects a menu item", () => {
    it("closed: Space on the menu button opens the menu", async () => {
      const f = await setup();
      f.invoker.focus();
      await press('Space');
      expect(isOpen(f.menu)).toBeTrue();
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("Space on an item with a submenu opens the submenu", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 3);
      await press('Space');
      expect(isOpen(f.submenu)).toBeTrue();
      expect(focusedIndex(f.submenuItems)).toBe(0);
    });

    it("closed: Enter on the menu button opens the menu", async () => {
      const f = await setup();
      f.invoker.focus();
      await press('Enter');
      expect(isOpen(f.menu)).toBeTrue();
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("Enter on an item with a submenu opens the submenu", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 3);
      await press('Enter');
      expect(isOpen(f.submenu)).toBeTrue();
      expect(focusedIndex(f.submenuItems)).toBe(0);
    });

    it("open: Space selects the focused item and closes the menu", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 0);
      await press('Space');
      expect(f.activated).toEqual([0]);
      expect(isOpen(f.menu)).toBeFalse();
    });

    it("open: Enter selects the focused item and closes the menu", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 0);
      await press('Enter');
      expect(f.activated).toEqual([0]);
      expect(isOpen(f.menu)).toBeFalse();
    });
  });

  // Spec: "Up and Down arrows" | "For closed menus: Opens menu For open menus: Moves focus to the next item"
  // spec: menus-baea5e, menus-e87531
  describe("Up and Down arrows: For closed menus: Opens menu For open menus: Moves focus to the next item", () => {
    it("closed: ArrowUp on the menu button opens the menu", async () => {
      const f = await setup();
      f.invoker.focus();
      await press('ArrowUp');
      expect(isOpen(f.menu)).toBeTrue();
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("closed: ArrowDown on the menu button opens the menu", async () => {
      const f = await setup();
      f.invoker.focus();
      await press('ArrowDown');
      expect(isOpen(f.menu)).toBeTrue();
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("ArrowUp moves focus to the previous item", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 1);
      await press('ArrowUp');
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("ArrowDown moves focus to the next item", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 0);
      await press('ArrowDown');
      expect(focusedIndex(f.items)).toBe(1);
    });
  });

  // Spec: "Left and Right arrows" | "Opens or closes a submenu"
  // spec: menus-69a087
  describe("Left and Right arrows: Opens or closes a submenu", () => {
    it("ArrowRight opens the submenu of the focused item", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 3);
      await press('ArrowRight');
      expect(isOpen(f.submenu)).toBeTrue();
      expect(focusedIndex(f.submenuItems)).toBe(0);
    });

    it("ArrowLeft closes the submenu and focuses its item", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 3);
      await press('ArrowRight');
      await press('ArrowLeft');
      expect(isOpen(f.submenu)).toBeFalse();
      expect(isOpen(f.menu)).toBeTrue();
      expect(focusedIndex(f.items)).toBe(3);
    });
  });

  // Spec: "Letters" | "Focus moves to the next menu item starting with letter"
  // spec: menus-151588
  describe("Letters: Focus moves to the next menu item starting with letter", () => {
    it("a letter moves focus to the next item starting with it", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 0);
      await press('p');
      expect(focusedIndex(f.items)).toBe(2);
    });
  });

  // Spec: "Escape" | "Closes menu"
  // spec: menus-235f42
  describe("Escape: Closes menu", () => {
    it("Escape closes the menu and returns focus to the menu button", async () => {
      const f = await setup();
      await openMenu(f);
      await focusItem(f, 0);
      await press('Escape');
      expect(isOpen(f.menu)).toBeFalse();
      expect(isFocused(f.invoker)).toBeTrue();
    });
  });
});
